import{_ as s,o as a,c as t,ag as o}from"./chunks/framework.D2veAa-g.js";const m=JSON.parse('{"title":"云原生架构相关技术","description":"","frontmatter":{"title":"云原生架构相关技术"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/云原生架构设计理论与实践（第二版）/云原生架构相关技术.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/云原生架构设计理论与实践（第二版）/云原生架构相关技术.md","lastUpdated":null}'),r={name:"架构师 在线刷题/51CT0题库 章节练习/云原生架构设计理论与实践（第二版）/云原生架构相关技术.md"};function i(e,l,n,c,u,d){return a(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="云原生架构相关技术" tabindex="-1">云原生架构相关技术 <a class="header-anchor" href="#云原生架构相关技术" aria-label="Permalink to &quot;云原生架构相关技术&quot;">​</a></h1><blockquote><p>共 6 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-关于某体育用品公司云原生解决方案的关键亮点-说法错误的是-。" tabindex="-1">Q1. 关于某体育用品公司云原生解决方案的关键亮点，说法错误的是（ ）。 <a class="header-anchor" href="#q1-关于某体育用品公司云原生解决方案的关键亮点-说法错误的是-。" aria-label="Permalink to &quot;Q1. 关于某体育用品公司云原生解决方案的关键亮点，说法错误的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 构建全渠道业务中台，整合多业务功能，打造共享商品中心等</li><li><strong>B.</strong> 采用 “烟囱式” 系统建设模式，延续传统架构优势</li><li><strong>C.</strong> 实现数据融通与聚合，为数字化决策等提供支撑</li><li><strong>D.</strong> 打造统一服务体验，将渠道数据与逻辑整合在共享服务平台</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q2-关于服务网格的主要技术实践-说法正确的是-。" tabindex="-1">Q2. 关于服务网格的主要技术实践，说法正确的是（ ）。 <a class="header-anchor" href="#q2-关于服务网格的主要技术实践-说法正确的是-。" aria-label="Permalink to &quot;Q2. 关于服务网格的主要技术实践，说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> Istio 项目仅定义了控制平面，未涉及数据平面相关内容</li><li><strong>B.</strong> Envoy 作为数据平面的代表，未获得 Google、Microsoft 等企业支持</li><li><strong>C.</strong> Linkerd 在数据平面的灵活性低，无法适配不同场景需求</li><li><strong>D.</strong> Consul 设计注重轻量级，在服务网格实践中有独特优势</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q3-关于无服务器技术-serverless-的特点-下列说法错误的是-。" tabindex="-1">Q3. 关于无服务器技术（Serverless）的特点，下列说法错误的是（ ）。 <a class="header-anchor" href="#q3-关于无服务器技术-serverless-的特点-下列说法错误的是-。" aria-label="Permalink to &quot;Q3. 关于无服务器技术（Serverless）的特点，下列说法错误的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 全托管的计算服务，客户只需编写代码构建应用，无需关注底层复杂运维</li><li><strong>B.</strong> 具备通用性，能适配云运维、AI、安全、物联网等工作负载类型的应用</li><li><strong>C.</strong> 按逻辑计费，企业使用无服务器资源时，完全不用为资源闲置付费</li><li><strong>D.</strong> 函数计算（Function as a Service，FaaS）是无服务器中具代表性的产品形态</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q4-在微服务架构的演进背景中-关于单体应用与微服务的说法-正确的是-。" tabindex="-1">Q4. 在微服务架构的演进背景中，关于单体应用与微服务的说法，正确的是（ ）。 <a class="header-anchor" href="#q4-在微服务架构的演进背景中-关于单体应用与微服务的说法-正确的是-。" aria-label="Permalink to &quot;Q4. 在微服务架构的演进背景中，关于单体应用与微服务的说法，正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 单体应用功能简单，不存在因功能复杂导致的开发和运维问题</li><li><strong>B.</strong> 微服务架构下，每个服务完成的功能在业务域划分上相互关联，不强调独立性</li><li><strong>C.</strong> 微服务的 “微” 只是指代码量少，和业务域划分、职责单一性无关</li><li><strong>D.</strong> 相较于单体应用，微服务架构在提升开发、部署等环节灵活性的同时，也提升了运维环节的复杂度</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q5-关于容器技术的描述-下列说法正确的是-。" tabindex="-1">Q5. 关于容器技术的描述，下列说法正确的是（ ）。 <a class="header-anchor" href="#q5-关于容器技术的描述-下列说法正确的是-。" aria-label="Permalink to &quot;Q5. 关于容器技术的描述，下列说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 容器作为标准化软件单元，将应用及其所有依赖打包后，仍会受不同计算环境限制</li><li><strong>B.</strong> 2008 年 Linux 提供的 cgroups 资源控制与 Linux Name Space 视图隔离方案，直接催生出 Docker 等容器引擎</li><li><strong>C.</strong> Docker 容器引擎的出现，未对操作系统内核轻量化改造产生影响</li><li><strong>D.</strong> 容器技术实现了应用与运行环境解耦，让应用更具灵活性、开放性和可运维性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q6-关于服务网格-service-mesh-的架构-以下描述正确的是-。" tabindex="-1">Q6. 关于服务网格（Service Mesh）的架构，以下描述正确的是（ ）。 <a class="header-anchor" href="#q6-关于服务网格-service-mesh-的架构-以下描述正确的是-。" aria-label="Permalink to &quot;Q6. 关于服务网格（Service Mesh）的架构，以下描述正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 服务网格由数据平面和应用平面组成</li><li><strong>B.</strong> 控制平面负责直接处理入站和出站数据包</li><li><strong>C.</strong> 数据平面由一组Sidecar代理构成，负责接管服务的进出流量</li><li><strong>D.</strong> Galley组件属于数据平面，负责执行策略和收集遥测数据</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details>',20)])])}const h=s(r,[["render",i]]);export{m as __pageData,h as default};
